window.DayNotes=[{q:"“Një panel me tregues duhet të të ndihmojë ta shohësh operacionin. Nuk duhet të zërë kurrë vendin e syve të tu.”",id:"note-01-dashboard",d:"20 shtator 2026",iso:"2026-09-20",img:"/media/notes/sq/01-dashboard.jpg?v=7c2ecc9e98"},{q:"“Nëse një problem ka nevojë për të njëjtën kujtesë çdo ditë, kujtesa nuk është sistemi.”",id:"note-02-reminder",d:"20 shtator 2026",iso:"2026-09-20",img:"/media/notes/sq/02-reminder.jpg?v=ca186830ce"},{q:"“Përgjegjësia fillon aty ku mbaron fjalia ‘dikush duhet ta bëjë’.”",id:"note-03-ownership",d:"20 shtator 2026",iso:"2026-09-20",img:"/media/notes/sq/03-ownership.jpg?v=2fb39bcc79"},{q:"“Turni i natës i nxjerr në pah proceset e dobëta, sepse ka më pak njerëz që t'i fshehin.”",id:"note-04-night-shift",d:"20 shtator 2026",iso:"2026-09-20",img:"/media/notes/sq/04-night-shift.jpg?v=97871d6c34"},{q:"“Në Excel, gabimi është një numër. Në rampë, ai ka një adresë.”",id:"note-01-excel",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/01-excel.jpg?v=98018a30c8"},{q:"“KPI-ja të tregon ku të shikosh. Nuk të tregon vetë çfarë ka ndodhur.”",id:"note-02-kpi",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/02-kpi.jpg?v=4e2a0111e0"},{q:"“Nëse menaxhon vetëm numrin, mund të ndëshkosh personin e gabuar.”",id:"note-03-the-number",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/03-the-number.jpg?v=3c8b46dc16"},{q:"“Një analizë e fryrë për t'u dukur bukur është më e rrezikshme se një analizë e paplotë që e pranon kufirin e vet.”",id:"note-04-analysis",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/04-analysis.jpg?v=922cb599f5"},{q:"“Mos u kap pas karriges që kishe dikur. Merr me vete atë që mësove ndërsa rrije ulur në të.”",id:"note-05-the-chair",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/05-the-chair.jpg?v=33f9c8e9dc"},{q:"“Ai që e bën punën nuk duhet të detyrohet ta kërkojë informacionin. Informacioni duhet të jetë aty ku ai e pret.”",id:"note-06-information",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/06-information.jpg?v=458a57511d"},{q:"“Nuk jam bërë më pak fleksibël. Jam bërë më pak i gatshëm ta lë fleksibilitetin të zëvendësojë sistemin.”",id:"note-07-flexibility",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/07-flexibility.jpg?v=54beef772a"},{q:"“Autoriteti pa titull nuk fitohet duke u sjellë sikur ke një titull. Fitohet duke qenë i dobishëm.”",id:"note-08-authority",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/08-authority.jpg?v=3861525229"},{q:"“Nisma dhe autoriteti për të vendosur janë dy gjëra të ndryshme.”",id:"note-09-initiative",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/09-initiative.jpg?v=67afa61cd3"},{q:"“Udhëheqja nuk është të bëhesh njeriu pa të cilin asgjë nuk funksionon. Është të ndihmosh që gjërat të funksionojnë edhe kur ti nuk je aty.”",id:"note-10-leadership",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/10-leadership.jpg?v=63aceac006"},{q:"“Ditën menaxhmenti sheh aktivitetin. Natën ti sheh gjurmët që ai ka lënë pas.”",id:"note-11-traces",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/11-traces.jpg?v=564f1e1325"},{q:"“Një problem që nuk hyn në dorëzimin e turnit nuk pushon së ekzistuari. Thjesht bëhet problem i dikujt që ende nuk e di se ekziston.”",id:"note-12-handover",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/12-handover.jpg?v=47b4bcb1e4"},{q:"“‘E raportuar’ dhe ‘e zgjidhur’ nuk janë e njëjta gjë.”",id:"note-13-reported",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/13-reported.jpg?v=516b8b4f5a"},{q:"“Një ekip që ka frikë të tregojë gabimet nuk ka më pak gabime.”",id:"note-14-fear",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/14-fear.jpg?v=af8cd40d05"},{q:"“Nëse rezultati varet nga prania e personit të duhur në turn, organizata ka njohuri, por ende nuk ka standard.”",id:"note-15-standard",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/15-standard.jpg?v=267a974759"},{q:"“Raportet më tregojnë ku të shikoj. Terreni më tregon çfarë po ndodh. Menaxherit i duhen të dyja.”",id:"note-16-reports",d:"4 tetor 2026",iso:"2026-10-04",img:"/media/notes/sq/16-reports.jpg?v=18d6fc09b8"},{q:"“Titulli mund të humbasë brenda një dite. Ajo që ke mësuar nuk humbet.”",id:"note-17-the-title",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/17-the-title.jpg?v=0d4adb7fe3"},{q:"“Tabela është pika e nisjes, jo përgjigjja.”",id:"note-18-the-table",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/18-the-table.jpg?v=623c569add"},{q:"“Njeriu duhet ta njohë standardin para se ta gjykosh pse nuk e zbaton.”",id:"note-19-know-the-standard",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/19-know-the-standard.jpg?v=e6f9ff4f60"},{q:"“Presioni mund të jetë i drejtë. Poshtërimi i njerëzve nuk është metodë menaxhimi.”",id:"note-20-pressure",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/20-pressure.jpg?v=064e066516"},{q:"“Nëse i njëjti gabim mund t'i ndodhë edhe personit tjetër, nuk ke ndryshuar sistemin. Ke ndërruar vetëm emrin në raport.”",id:"note-21-the-name",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/21-the-name.jpg?v=b7317f43bb"},{q:"“Presioni nuk duhet përcjellë poshtë si panik.”",id:"note-22-panic",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/22-panic.jpg?v=dfe660b872"},{q:"“Një KPI përmirësohet kur ndryshon procesin që e prodhon.”",id:"note-23-the-process",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/23-the-process.jpg?v=482c8c6007"},{q:"“Llogaridhënia nuk do të thotë të kërkosh një fajtor sa herë që një numër del i kuq. Do të thotë të gjesh kush përgjigjet për problemin dhe ta ndjekësh derisa të mbyllet.”",id:"note-24-accountability",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/24-accountability.jpg?v=10bf7f58c6"},{q:"“Prova e një SOP-je nuk është nëse e kupton autori i saj, por nëse dikush tjetër mund ta përdorë nën presion dhe të arrijë të njëjtin rezultat.”",id:"note-25-the-test",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/25-the-test.jpg?v=8e039e688b"},{q:"“Kur versioni zyrtar thotë një gjë dhe njerëzit në turn kanë mësuar një mënyrë tjetër, SOP-ja ka pushuar së qeni standard.”",id:"note-26-two-versions",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/26-two-versions.jpg?v=13844e8866"},{q:"“Një problem që e di vetëm një person është ende një problem i organizatës. Kur dokumentohet, mund t'i caktohet përgjegjësi.”",id:"note-27-written-down",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/27-written-down.jpg?v=70cef26e96"},{q:"“Shumë gabime nuk lindin nga mungesa e aftësisë. Lindin nga fjalia: ‘Do ta bëjmë më vonë.’”",id:"note-28-later",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/28-later.jpg?v=700e8b8d0b"},{q:"“Një gabim i vetëm mund të jetë rastësi. I njëjti gabim disa herë është proces.”",id:"note-29-twice",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/29-twice.jpg?v=a8fb5ae687"},{q:"“Dorëzimi i turnit nuk është thjesht kalim informacioni. Është kalim përgjegjësie.”",id:"note-30-responsibility",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/30-responsibility.jpg?v=53be389ce6"},{q:"“Nëse vazhdimisht mbulon boshllëqet e një sistemi, krijon përshtypjen se sistemi funksionon. Sepse dikush e shpëton gjithmonë.”",id:"note-31-the-gaps",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/31-the-gaps.jpg?v=49cb1a7a7c"},{q:"“Standardizimi nuk synon t'ua heqë njerëzve të menduarit. Synon që të mos shpikin nga e para atë që organizata duhet ta dijë tashmë.”",id:"note-32-reinvent",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/32-reinvent.jpg?v=752a1670cf"},{q:"“Të dhënat duhet të më çojnë në terren. Dhe terreni duhet të më ndihmojë të kuptoj të dhënat.”",id:"note-33-the-floor",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/33-the-floor.jpg?v=19444af1a2"},{q:"“Në 30 ditët e para, një menaxher i ri nuk ka nevojë për 30 zgjidhje. Ka nevojë për 30 pyetje të mira.”",id:"note-34-thirty-questions",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/34-thirty-questions.jpg?v=7fa42f0968"},{q:"“Një hap që duket i panevojshëm mund të jetë pikërisht hapi ku mbështetet dikush tjetër.”",id:"note-35-dependencies",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/35-dependencies.jpg?v=533c33531d"},{q:"“Problemi nuk ishte mungesa e informacionit. Ishte se informacioni nuk të tregonte shpejt ku je dhe çfarë vjen më pas.”",id:"note-36-scattered",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/36-scattered.jpg?v=970894dbb8"},{q:"“Dorëzimi i turnit të tregon çfarë gjendjeje po trashëgon. Takimi para turnit vendos çfarë ka rëndësi tani.”",id:"note-37-inherit-decide",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/37-inherit-decide.jpg?v=89e88399d8"},{q:"“Nëse thua vetëm numrin dhe turni fillon, ke dhënë informacion, jo drejtim.”",id:"note-38-direction",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/38-direction.jpg?v=08fde32b2d"},{q:"“Takimi para turnit ka kuptim kur një KPI kthehet në një sjellje ose veprim të qartë.”",id:"note-39-kpi-to-action",d:"5 tetor 2026",iso:"2026-10-05",img:"/media/notes/sq/39-kpi-to-action.jpg?v=38a5b8903c"},{q:"“Nëse standardi i trajnimit është ‘shiko si e bëj unë’, atëherë çdo punonjës i ri merr një version tjetër të të njëjtës punë.”",id:"note-40-versions",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/40-versions.jpg?v=1657dd1759"},{q:"“‘Po, e kuptova’ nuk është provë. Bëje vetë. Ma shpjego pse. Më trego çfarë bën kur del një përjashtim.”",id:"note-41-proof",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/41-proof.jpg?v=7940720630"},{q:"“Trajnimi nuk matet me atë se sa mirë shpjegoi trajneri. Matet me atë se sa i njëtrajtshëm bëhet rezultati pasi trajneri largohet.”",id:"note-42-trainer-leaves",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/42-trainer-leaves.jpg?v=887cfcf143"},{q:"“Një sistem i mirë për t'i çuar çështjet më lart nuk i mëson njerëzit të kërkojnë leje për çdo gjë. I mëson të kuptojnë kufirin e vendimit të tyre.”",id:"note-43-decision-limit",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/43-decision-limit.jpg?v=56d6ae585d"},{q:"“Çoje më lart vendimin, jo paqartësinë që mund ta kishe sqaruar vetë.”",id:"note-44-escalate-the-decision",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/44-escalate-the-decision.jpg?v=9aab601974"},{q:"“Marrja përsipër nuk do të thotë ta zgjidhësh vetë. Do të thotë ta çosh problemin, me informacionin e duhur, aty ku mund të merret vendimi i duhur.”",id:"note-45-ownership",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/45-ownership.jpg?v=6200b2739f"},{q:"“Vendi ku matet një gabim nuk është domosdoshmërisht vendi ku ai ka lindur.”",id:"note-46-measured-born",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/46-measured-born.jpg?v=4cf30d28cc"},{q:"“Informacioni i dërguar nuk është gjithmonë informacion i marrë. Dhe një problem i raportuar nuk është domosdoshmërisht problem i zgjidhur.”",id:"note-47-sent-received",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/47-sent-received.jpg?v=a712ff4d2f"},{q:"“Një proces nuk përfundon kur unë e dorëzoj punën. Përfundon kur ekipi tjetër mund ta vazhdojë pa humbur asgjë.”",id:"note-48-process-ends",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/48-process-ends.jpg?v=c543869c1b"},{q:"“Një KPI mund të jetë matematikisht e saktë dhe interpretimi i saj të jetë i padrejtë.”",id:"note-49-correct-unfair",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/49-correct-unfair.jpg?v=fe9347a15a"},{q:"“Detyra e menaxherit është të ndajë atë që personi kontrollon nga ajo që duhet korrigjuar në sistem.”",id:"note-50-person-system",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/50-person-system.jpg?v=3f0580e513"},{q:"“Një numër tregon rezultatin. Tjetri tregon arsyen. Pa të dytin, numrat shndërrohen në raportim pa mësim.”",id:"note-51-result-reason",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/51-result-reason.jpg?v=3f59feb567"},{q:"“Presioni mund të jetë i drejtë. Poshtërimi jo.”",id:"note-52-pressure",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/52-pressure.jpg?v=69ed0f1013"},{q:"“Autoriteti formal të jep të drejtën për të marrë vendime. Besimi ndërtohet me mënyrën si i merr.”",id:"note-53-authority-trust",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/53-authority-trust.jpg?v=2f3d379e25"},{q:"“Një gabim duhet të na çojë te dy pyetje: çfarë nuk funksionoi në proces dhe çfarë përgjegjësie kishte personi?”",id:"note-54-two-questions",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/54-two-questions.jpg?v=a35f30324e"},{q:"“Të mos e flasësh ende mirë një gjuhë nuk do të thotë se nuk je i zoti në punën tënde.”",id:"note-55-language-ability",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/55-language-ability.jpg?v=2e5151d041"},{q:"“‘E kuptove?’ nuk mjafton gjithmonë. ‘Më trego si do ta bëje’ mjafton.”",id:"note-56-show-me",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/56-show-me.jpg?v=68f68de708"},{q:"“Një standard i mirë matet me atë se sa saktë e zbatojnë njerëz të ndryshëm, edhe kur nuk flasin të njëjtën gjuhë.”",id:"note-57-standard-measured",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/57-standard-measured.jpg?v=3569de21f6"},{q:"“Kërko procedurën, jo dokumentin.”",id:"note-58-search-procedure",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/58-search-procedure.jpg?v=d077a1d98f"},{q:"“Mund ta tregosh metodën si e organizon informacionin pa publikuar të dhënat e ndjeshme ku mbështetet puna.”",id:"note-59-method-not-data",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/59-method-not-data.jpg?v=ebb8532df5"},{q:"“Një SOP bëhet e dobishme kur personi që ka nevojë për të mund ta gjejë, ta kuptojë dhe ta zbatojë në momentin e duhur.”",id:"note-60-sop-useful",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/60-sop-useful.jpg?v=2de335d5dc"},{q:"“Partneri nuk menaxhohet si punonjës. Ai duhet të ketë arsye për të vazhduar të punojë me ty.”",id:"note-61-partner",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/61-partner.jpg?v=e7b54f37b9"},{q:"“Autoriteti mund të të ndihmojë të marrësh një vendim. Besimi është ai që e mban gjallë bashkëpunimin.”",id:"note-62-authority-trust",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/62-authority-trust.jpg?v=792140fa73"},{q:"“Qëllimi nuk është një ekip që nuk punon dot pa mua. Është një mënyrë pune që vazhdon edhe kur unë nuk jam aty.”",id:"note-63-runs-without-me",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/63-runs-without-me.jpg?v=4e56e8698c"},{q:"“Dokumenti të tregon si duhet të jetë puna. Njerëzit të tregojnë si është.”",id:"note-64-document-people",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/64-document-people.jpg?v=f4bd252d4e"},{q:"“Hyr për të kuptuar, jo për të treguar sa di.”",id:"note-65-walk-in",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/65-walk-in.jpg?v=ec0caea78b"},{q:"“Mos ndrysho diçka vetëm për të treguar se ke ardhur të sjellësh ndryshim.”",id:"note-66-change-to-show",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/66-change-to-show.jpg?v=3b4c4f5428"},{q:"“Ditët e para të një personi të ri janë një burim informacioni që shumica e organizatave e shpërdorojnë.”",id:"note-67-new-eyes",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/67-new-eyes.jpg?v=87abb2b8ae"},{q:"“Një detyrë pa përgjegjës është thuajse një detyrë që nuk do ta bëjë askush.”",id:"note-68-no-owner",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/68-no-owner.jpg?v=6bf0f25484"},{q:"“Një takim i mirë para turnit nuk matet me sa gjëra u thanë. Matet me atë që ekipi bën ndryshe në orën e parë të turnit.”",id:"note-69-first-hour",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/69-first-hour.jpg?v=f6940f0af9"},{q:"“Informacioni të jep pjesët. Sistemi të jep rendin, arsyen dhe pikën ku e di që mund të vazhdosh vetë.”",id:"note-70-pieces-order",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/70-pieces-order.jpg?v=625d6c00b4"},{q:"“Pa një SOP që përdoret realisht, trajnimi bëhet kopjim.”",id:"note-71-copying",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/71-copying.jpg?v=b3d87ea384"},{q:"“Nisma ka kuptim brenda kufirit që njeh. Jashtë tij, improvizimi nuk është guxim. Është rrezik.”",id:"note-72-improvising",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/72-improvising.jpg?v=90044557c6"},{q:"“Një operacion që varet nga kush ishte në turn nuk është ende një operacion që ecën pa ty.”",id:"note-73-who-was-on-shift",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/73-who-was-on-shift.jpg?v=95c2bdab05"},{q:"“Një njoftim i plotë që shkon lart me vonesë është më i keq se një njoftim i shkurtër që shkon në kohë.”",id:"note-74-late-escalation",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/74-late-escalation.jpg?v=b690791a03"},{q:"“Një departament mund ta bëjë punën e vet shumë mirë, e megjithatë operacioni të dështojë.”",id:"note-75-between-departments",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/75-between-departments.jpg?v=cc3ccbac9a"},{q:"“Numri të tregon ku ta kërkosh problemin, jo kush e shkaktoi.”",id:"note-76-where-not-who",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/76-where-not-who.jpg?v=b7fd41b0ad"},{q:"“Një KPI që ekipi e beson nuk është ajo që del gjithmonë e gjelbër. Është ajo që mat qartë dhe lexohet me drejtësi.”",id:"note-77-not-always-green",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/77-not-always-green.jpg?v=4e4f612174"},{q:"“Nëse e nis bisedën nga përgjegjësia, ke gjykuar para se të dëgjosh.”",id:"note-78-judged-before-listening",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/78-judged-before-listening.jpg?v=10877daeec"},{q:"“Një standard i paqartë mbetet i paqartë në çdo gjuhë që ta përkthesh.”",id:"note-79-unclear-any-language",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/79-unclear-any-language.jpg?v=cc93ad965c"},{q:"“Kur dikush nuk e kupton një udhëzim, detyra jonë nuk mbaron duke ia përsëritur të njëjtën fjali më fort.”",id:"note-80-louder",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/80-louder.jpg?v=0802273a71"},{q:"“Fakti që unë e kuptoj një udhëzim nuk do të thotë se do ta kuptojë njësoj dikush që e sheh për herë të parë.”",id:"note-81-first-time-reader",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/81-first-time-reader.jpg?v=9afad2ebf4"},{q:"“Është më mirë të shpjegosh me kohë një kufizim sesa të krijosh një pritshmëri që nuk mund ta përmbushësh.”",id:"note-82-explain-a-limit",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/82-explain-a-limit.jpg?v=190ef02da5"},{q:"“Vlera e një menaxheri nuk është në sa gjëra kalojnë nëpër duart e tij, por në sa mirë ecin ato kur nuk kalojnë më.”",id:"note-83-through-his-hands",d:"8 tetor 2026",iso:"2026-10-08",img:"/media/notes/sq/83-through-his-hands.jpg?v=ae8bb350f4"},{q:"“Si e zgjidhim, pse ndodhi dhe çfarë ndryshojmë që të mos na kthehet përsëri?”",id:"note-84-why-did-it-happen",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/84-why-did-it-happen.jpg?v=ae345b508d"},{q:"“Dhjetë minutat para turnit nuk janë për të treguar gjithçka që dimë. Janë për të vendosur çfarë duhet të dijë ekipi para se të fillojë puna.”",id:"note-85-ten-minutes",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/85-ten-minutes.jpg?v=94727d4246"},{q:"“A kam ndërtuar një operacion që funksionon si sistem, apo një operacion që varet nga prania ime?”",id:"note-86-system-or-presence",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/86-system-or-presence.jpg?v=07378a4285"},{q:"“Në cilën pikë puna ndërroi duar dhe çfarë informacioni humbi gjatë atij kalimi?”",id:"note-87-changed-hands",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/87-changed-hands.jpg?v=bdb3eaad29"},{q:"“Shiko. Bëje bashkë me mua. Bëje ti ndërsa unë shikoj. Bëje vetëm. Pastaj ma shpjego.”",id:"note-88-watch-do-explain",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/88-watch-do-explain.jpg?v=29d108b209"},{q:"“Nuk do ta shpërfill vetëm sepse ‘nuk është e imja’.”",id:"note-89-not-mine",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/89-not-mine.jpg?v=5b9e15fe8d"},{q:"“Menaxhimi i mirë kërkon t'i shohësh të dyja, pa kërkuar fajtor me çdo kusht dhe pa e fshehur përgjegjësinë kur ajo ekziston.”",id:"note-90-see-both",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/90-see-both.jpg?v=a16368bff9"},{q:"“Një KPI të tregon se ke një problem. Nuk të tregon automatikisht ku ka filluar dhe kush e ka shkaktuar.”",id:"note-91-kpi-tells-problem",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/91-kpi-tells-problem.jpg?v=3afb82944e"},{q:"“Menaxhimi i dëmeve nuk duhet të jetë vetëm përpjekje për të ulur përqindjen në raport. Duhet të jetë përpjekje për të kuptuar dhe parandaluar dëmet në proces.”",id:"note-92-managing-damage-should",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/92-managing-damage-should.jpg?v=f5af4ddd9b"},{q:"“Qëllimi nuk është një përqindje më e ulët në raport. Është një dëm më pak në proces.”",id:"note-93-goal-lower-percentage",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/93-goal-lower-percentage.jpg?v=d9ec7945ca"},{q:"“Një porosi mund t'i mbërrijë klientit e paplotë, por problemi mund të ketë nisur shumë përpara dorëzimit.”",id:"note-94-order-reach-customer",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/94-order-reach-customer.jpg?v=2d41aa9a0a"},{q:"“Porositë e paplota nuk duhen parë vetëm si numër negativ apo gabim i shoferit. Duhet të na ndihmojnë të kuptojmë ku humbi produkti ose informacioni dhe si mund ta parandalojmë përsëritjen.”",id:"note-95-incomplete-should-seen",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/95-incomplete-should-seen.jpg?v=ba13d0ddfe"},{q:"“Kontrolli më i mirë nuk është ai që numëron porositë e paplota. Është ai që i ndal para se të nisen.”",id:"note-96-best-check-one",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/96-best-check-one.jpg?v=b65e5d1958"},{q:"“Gemba nuk duhet të jetë një shëtitje kontrolli. Duhet të jetë një mënyrë për të kuptuar procesin, për të dëgjuar njerëzit dhe për të zbuluar pengesat që numrat nuk i shpjegojnë.”",id:"note-97-gemba-should-inspection",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/97-gemba-should-inspection.jpg?v=211976a023"},{q:"“Një menaxher që sheh vetëm raportin njeh rezultatin e punës. Një menaxher që shkon edhe në terren ka mundësi të kuptojë si lind ai rezultat.”",id:"note-98-manager-who-only",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/98-manager-who-only.jpg?v=8fd4e3c63e"},{q:"“Një rampë e organizuar nuk është vetëm më e pastër. Ajo ndihmon që ngarkimi të jetë më i qartë, gabimet të dallohen më shpejt dhe njerëzit të punojnë në kushte më të sigurta.”",id:"note-99-organised-ramp-cleaner",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/99-organised-ramp-cleaner.jpg?v=cc33c5f424"},{q:"“Rregulli nuk provohet me një poster në mur. Provohet nga mënyra si ecën vendi i punës në një ditë të vështirë.”",id:"note-100-order-proved-by",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/100-order-proved-by.jpg?v=fbf00297ba"},{q:"“6S nuk duhet të jetë një aktivitet që bëhet përpara një kontrolli. Duhet të jetë pjesë e mënyrës së përditshme të punës.”",id:"note-101-6s-should-something",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/101-6s-should-something.jpg?v=1d7e5363d6"},{q:"“Nëse ndryshojmë rregullat pas çdo luhatjeje, rrezikojmë të krijojmë më shumë paqëndrueshmëri sesa përmirësim.”",id:"note-102-if-change-rules",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/102-if-change-rules.jpg?v=9696d82910"},{q:"“Një menaxher duhet të dijë kur të ndërhyjë menjëherë dhe kur të mbledhë më shumë informacion.”",id:"note-103-manager-know-when",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/103-manager-know-when.jpg?v=7238b94f93"},{q:"“KPI-ja tregon çfarë ndodhi. Trendi ndihmon të kuptojmë nëse po ndryshon diçka. Analiza e procesit na ndihmon të vendosim çfarë duhet bërë.”",id:"note-104-kpi-shows-happened",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/104-kpi-shows-happened.jpg?v=db6d98f29c"},{q:"“Një ditë e keqe është sinjal për të kontrolluar. Nuk është automatikisht provë se i gjithë procesi duhet ndryshuar.”",id:"note-105-bad-day-signal",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/105-bad-day-signal.jpg?v=2f02923ff9"},{q:"“Vlera e DMAIC qëndron te disiplina për të mos kaluar menjëherë nga problemi te zgjidhja.”",id:"note-106-value-dmaic-lies",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/106-value-dmaic-lies.jpg?v=0bd15cea12"},{q:"“Një problem nuk quhet i zgjidhur vetëm sepse sot nuk u përsërit.”",id:"note-107-problem-solved-happen",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/107-problem-solved-happen.jpg?v=a8d9a8457f"},{q:"“Kur nuk e sheh automjetin, duhet të kesh një mënyrë të besueshme për të kuptuar çfarë po ndodh me të.”",id:"note-108-when-cannot-see",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/108-when-cannot-see.jpg?v=3f4013fb15"},{q:"“Koordinimi në distancë nuk është thjesht t'u japësh udhëzime shoferëve. Është të ndërtosh një mënyrë komunikimi ku problemet bëhen të dukshme, përgjegjësitë janë të qarta dhe vendimet merren në kohë.”",id:"note-109-remote-coordination-giving",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/109-remote-coordination-giving.jpg?v=c66cc60efd"},{q:"“Presioni nuk i krijon gjithmonë problemet. Shpesh i bën më të dukshme.”",id:"note-110-pressure-always-create",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/110-pressure-always-create.jpg?v=797ae204cd"},{q:"“Kapaciteti nuk është vetëm numri i njerëzve që ke në dispozicion. Është numri i njerëzve që mund ta kryejnë punën sipas standardit.”",id:"note-111-capacity-number-people",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/111-capacity-number-people.jpg?v=62f757cc7d"},{q:"“Standardi nuk provohet në ditën kur gjithçka shkon sipas planit. Provohet në ditën kur plani nuk mjafton.”",id:"note-112-standard-proved-day",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/112-standard-proved-day.jpg?v=5cf435d8dd"},{q:"“Gjatë natës, mundësitë për zgjidhje nuk janë gjithmonë të njëjta si gjatë ditës. Por kjo nuk do të thotë që përgjegjësia për problemin duhet të humbasë.”",id:"note-113-night-options-solution",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/113-night-options-solution.jpg?v=bc0eed3a78"},{q:"“Një ankesë nuk mbyllet vetëm sepse mysafiri largohet nga recepsioni.”",id:"note-114-complaint-closed-guest",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/114-complaint-closed-guest.jpg?v=6c774fb66d"},{q:"“Profesionalizmi është të dëgjosh, të verifikosh, të bësh atë që ke në kompetencë dhe të sigurohesh që puna të vazhdojë kur duhet të përfshihet dikush tjetër.”",id:"note-115-professionalism-listening-checking",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/115-professionalism-listening-checking.jpg?v=1d3597d34b"},{q:"“Mysafiri nuk duhet ta paguajë me kohë dhe nerva faktin që hoteli punon me turne.”",id:"note-116-guest-should-pay",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/116-guest-should-pay.jpg?v=f1fe9a5bc5"},{q:"“Një standard që ekziston vetëm në dokument nuk është domosdoshmërisht një standard që zbatohet.”",id:"note-117-standard-exists-only",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/117-standard-exists-only.jpg?v=c92c51eec3"},{q:"“A kemi ndërtuar një përmirësim që bëhet pjesë e sistemit, apo një rezultat të përkohshëm që varet nga vëmendja e menaxherit?”",id:"note-118-built-improvement-becomes",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/118-built-improvement-becomes.jpg?v=366c0dac43"},{q:"“Përmirësimi i vërtetë nuk është ai që funksionon vetëm kur menaxheri është aty. Është ai që vazhdon të funksionojë edhe kur menaxheri largohet.”",id:"note-119-real-improvement-kind",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/119-real-improvement-kind.jpg?v=db8bff6c7e"},{q:"“Një menaxher i mirë mund ta përmirësojë një ditë pune. Një sistem i mirë e mban përmirësimin gjallë edhe ditën kur menaxheri nuk është aty.”",id:"note-120-good-manager-improve",d:"10 tetor 2026",iso:"2026-10-10",img:"/media/notes/sq/120-good-manager-improve.jpg?v=31c8e46114"},{q:"“Industria ndryshon. Ajo që kontrollon ndryshon. Por problemi i menaxhimit mbetet i njëjtë: nëse informacioni, përgjegjësia dhe ekzekutimi nuk takohen në të njëjtën pikë, diku do të dalë një gabim.”",id:"note-121-industry-changes-problem",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/121-industry-changes-problem.jpg?v=626f8235f7"},{q:"“Klientit nuk i intereson shumë cili departament bëri gabimin. Ai sheh vetëm kompaninë përballë tij.”",id:"note-122-customer-sees-company",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/122-customer-sees-company.jpg?v=ea65e3de5f"},{q:"“Menaxhimi nuk është gjithmonë të kesh autoritet mbi dikë. Shpesh është të arrish që njerëz mbi të cilët nuk ke autoritet të punojnë në të njëjtin drejtim me ty.”",id:"note-123-without-authority-direction",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/123-without-authority-direction.jpg?v=c145bd684a"},{q:"“Industrinë mund ta mësosh. Më e vështirë është të mësosh të shohësh kur një proces nuk funksionon, të mos i kalosh problemit anash dhe ta marrësh përsipër deri në fund.”",id:"note-124-learn-the-industry",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/124-learn-the-industry.jpg?v=8e59876acf"},{q:"“Mos hyr në punën e re duke pritur që të tjerët të respektojnë atë që ke qenë. Fillo të tregosh çfarë di të bësh aty ku je.”",id:"note-125-show-what-you-can",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/125-show-what-you-can.jpg?v=9f0d173c29"},{q:"“Po të kisha menduar se disa punë ishin poshtë meje, ndoshta nuk do ta kisha mësuar kurrë atë që më duhej për t'u ngritur përsëri.”",id:"note-126-jobs-beneath-me",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/126-jobs-beneath-me.jpg?v=abdd53d20f"},{q:"“Terreni nuk është vetëm vend për të parë. Është vend për të rindërtuar atë që ka ndodhur.”",id:"note-127-floor-reconstruct",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/127-floor-reconstruct.jpg?v=ef3c3b3257"},{q:"“Ajo që sheh duhet shënuar, përndryshe nesër është vetëm një kujtim.”",id:"note-128-written-down-memory",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/128-written-down-memory.jpg?v=82a385fbc9"},{q:"“Respekti nuk është të mos i kërkosh llogari njeriut. Respekti është t'ia bësh të qartë standardin, ta dëgjosh para se ta gjykosh, dhe kur përgjegjësia është e tij, të mos ia fshehësh.”",id:"note-129-respect-accountable",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/129-respect-accountable.jpg?v=6c3637e6a4"},{q:"“Standardi mund të jetë shumë i rreptë pa e trajtuar njeriun si numër.”",id:"note-130-standard-strong-number",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/130-standard-strong-number.jpg?v=b953bb1e94"},{q:"“Pareto nuk të jep të vërtetën nëse të dhënat që i jep nuk e pasqyrojnë atë.”",id:"note-131-pareto-truth",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/131-pareto-truth.jpg?v=8bcff04022"},{q:"“Kur e vetmja përgjigje e analizës është ‘punonjësi ishte i pakujdesshëm’, shpeshherë analiza është ndalur para kohe.”",id:"note-132-analysis-ended-early",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/132-analysis-ended-early.jpg?v=591bf4a3fb"},{q:"“Nëse një proces funksionon vetëm sepse një punonjës i mirë e mban mend, atëherë nuk ke ende një proces të mirë.”",id:"note-133-good-person-remembers",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/133-good-person-remembers.jpg?v=66624e05e0"},{q:"“Procesi është i rëndësishëm, por njerëzit nuk janë procese. Një punonjës mund të ketë të njëjtën detyrë si dje dhe të vijë sot në punë në një gjendje krejt tjetër.”",id:"note-134-people-not-processes",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/134-people-not-processes.jpg?v=adbee88fcc"},{q:"“Nëse një proces funksiononte sepse unë e dija, sot do të përpiqesha që ta dinte sistemi.”",id:"note-135-system-know-it",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/135-system-know-it.jpg?v=883ecc7431"},{q:"“Një mesazh që kërkon tri pyetje pasuese për t'u kuptuar e ka humbur kohën që duhej të kursente.”",id:"note-136-message-follow-up",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/136-message-follow-up.jpg?v=d10e6a0ec1"},{q:"“Një vonesë është rast. E njëjta vonesë, në të njëjtin vend, disa ditë me radhë, është skemë që përsëritet.”",id:"note-137-delay-pattern",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/137-delay-pattern.jpg?v=4093fe4b7e"},{q:"“Në rampë, problemi të del përpara. Nga distanca, ose e kërkon, ose ke ndërtuar një mënyrë që ai të të vijë vetë.”",id:"note-138-come-to-you",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/138-come-to-you.jpg?v=983d15f20c"},{q:"“Nuk ke nevojë për një certifikatë Black Belt për të bërë pyetje të mira. Por nuk mjafton as ta njohësh emrin e metodës për të pretenduar se e ke zbatuar.”",id:"note-139-name-of-method",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/139-name-of-method.jpg?v=89811c0039"},{q:"“Nëse një përmirësim mbahet vetëm sa është aty një person, nuk ishte përmirësim i procesit. Ishte prania e një personi.”",id:"note-140-one-persons-presence",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/140-one-persons-presence.jpg?v=4a3b849af3"},{q:"“Një proces i kontrolluar sillet ndryshe kur menaxheri është aty.”",id:"note-141-inspected-behaves",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/141-inspected-behaves.jpg?v=8ccadacfc4"},{q:"“Dikush e sheh problemin, pyet për të, dhe pyetja mbetet pa përgjigje. Të nesërmen problemi është ende aty, por tani duket normal.”",id:"note-142-looks-normal",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/142-looks-normal.jpg?v=5df20eef86"},{q:"“Një SOP që vetëm lexohet mund të duket shumë profesionale. Por kur fillon presioni i turnit, askush nuk ka kohë të lexojë një manual.”",id:"note-143-manual-pressure",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/143-manual-pressure.jpg?v=a82b2b5233"},{q:"“Një dokument të tregon si duhet bërë puna. Një SOP e mirë të ndihmon ta bësh punën saktë pikërisht kur ke nevojë për të.”",id:"note-144-sop-right-moment",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/144-sop-right-moment.jpg?v=834ddb92e6"},{q:"“Një turn nate nuk përfundon kur mbyllet sistemi. Përfundon kur personi që vjen pas meje e kupton qartë çfarë ndodhi, çfarë u zgjidh dhe çfarë ka mbetur për t'u ndjekur.”",id:"note-145-night-shift-ends",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/145-night-shift-ends.jpg?v=69a77771b8"},{q:"“Përgjegjësia nuk është të marrësh çdo vendim. Përgjegjësia është të dish cilin vendim mund ta marrësh vetë dhe cilin nuk duhet ta marrësh.”",id:"note-146-which-decision",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/146-which-decision.jpg?v=71dbab01ea"},{q:"“Një raport i mirë nuk duhet vetëm të tregojë të kaluarën. Duhet ta bëjë më të sigurt ditën që po fillon.”",id:"note-147-report-safer",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/147-report-safer.jpg?v=eeae581896"},{q:"“Nuk doja të mbaja mend ku ndodhej çdo dokument. Doja të dija ku të shkoja për përgjigjen e duhur.”",id:"note-148-where-to-go",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/148-where-to-go.jpg?v=b2d4dae40c"},{q:"“Një menaxher mund të jetë kërkues, i vendosur dhe shumë i qartë, pa e cenuar dinjitetin e personit që ka përballë.”",id:"note-149-demanding-dignity",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/149-demanding-dignity.jpg?v=8628261b60"},{q:"“Qëllimi i bisedës pas gabimit nuk është që punonjësi të largohet me frikë nga gabimi i radhës, por që të largohet duke ditur çfarë të bëjë ndryshe.”",id:"note-150-leave-knowing",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/150-leave-knowing.jpg?v=fc371df982"},{q:"“Kur çdo gjë ka vendin e vet, gjëja që nuk është në vend bie në sy. Kur nuk ka vend të caktuar për asgjë, asgjë nuk duket jashtë vendit.”",id:"note-151-out-of-place",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/151-out-of-place.jpg?v=dbda7972ad"},{q:"“Siguria nuk është S-ja e fundit që i shtohet listës. Është arsyeja pse lista ekziston.”",id:"note-152-reason-list-exists",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/152-reason-list-exists.jpg?v=2052ff2f5a"},{q:"“Një zonë e rregulluar me një problem të hapur që askush nuk e di nuk është zonë e rregulluar.”",id:"note-153-tidy-area",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/153-tidy-area.jpg?v=c08888d487"},{q:"“Një plan që funksionon vetëm kur gjithçka shkon sipas parashikimit nuk është plan për ditën e rëndë. Është përshkrim i ditës së zakonshme.”",id:"note-154-ordinary-day-plan",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/154-ordinary-day-plan.jpg?v=8dd1020ccd"},{q:"“Në ditën e rëndë, diçka do të shtyhet. Pyetja është nëse e ke vendosur më parë çfarë nuk shtyhet kurrë, apo e vendos në mes të presionit.”",id:"note-155-never-pushed-back",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/155-never-pushed-back.jpg?v=7033ba7dd8"},{q:"“Një standard që mund të respektohet vetëm kur ka kohë të lirë nuk është standard. Është dëshirë.”",id:"note-156-standard-wish",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/156-standard-wish.jpg?v=fe1bd5bf30"},{q:"“Një përmirësim që varet nga vëmendja e menaxherit zgjat sa vëmendja.”",id:"note-157-attention-lasts",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/157-attention-lasts.jpg?v=c79bc82ece"},{q:"“Përqindja të thotë sa. Pyetjet të thonë ku. Dhe ndryshimi nis te ‘ku’-ja.”",id:"note-158-only-where-changed",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/158-only-where-changed.jpg?v=30a237d5d0"},{q:"“Te dera e klientit, një çantë që mungon është ankesë. Në rampë, është ende pyetje.”",id:"note-159-still-a-question",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/159-still-a-question.jpg?v=6f14b4cd18"},{q:"“Standardi nuk thotë vetëm çfarë bëhet. Thotë edhe ku bëhet.”",id:"note-160-also-says-where",d:"12 tetor 2026",iso:"2026-10-12",img:"/media/notes/sq/160-also-says-where.jpg?v=c7ae409e59"},{q:"“Sistemi është më i shpejtë se ti në gjithçka që i është thënë. Nuk di asgjë nga ajo që nuk i është thënë. Dhe shumica e asaj që di terreni nuk i është thënë kurrë askujt.”",id:"note-161-system-faster-than",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/161-system-faster-than.jpg?v=2dc43533d0"},{q:"“Sistemi vendos i pari. Ty të mbetet pjesa që nuk i është thënë kurrë, dhe përgjegjësia për të gjitha.”",id:"note-162-system-decides-first",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/162-system-decides-first.jpg?v=daff5cad56"},{q:"“Mos e ngatërro humbjen e titullit me humbjen e vlerës sate profesionale.”",id:"note-163-confuse-losing-title",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/163-confuse-losing-title.jpg?v=9c01388f54"},{q:"“Një rregull i tillë duket i vogël në letër. Në rampë është dallimi mes një problemi që kapet në kohë dhe një klienti që merr një porosi të paplotë.”",id:"note-164-rule-like-looks",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/164-rule-like-looks.jpg?v=b840739950"},{q:"“Standardi nuk ishte një poster në mur. Shoqërohej me pritshmëri, kontrolle dhe llogaridhënie.”",id:"note-165-standard-was-poster",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/165-standard-was-poster.jpg?v=72dc80f736"},{q:"“Kategoria e gabuar të çon me shumë siguri te shkaku i gabuar.”",id:"note-166-wrong-category-leads",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/166-wrong-category-leads.jpg?v=856d6168bd"},{q:"“Të marrësh më shumë përgjegjësi nuk do të thotë të marrësh vendime që nuk të takojnë.”",id:"note-167-taking-more-responsibility",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/167-taking-more-responsibility.jpg?v=e630d3797f"},{q:"“Titujt e punës ndryshojnë më shpejt se natyra njerëzore. Presioni, keqkuptimi, përgjegjësia dhe nevoja për komunikim ekzistojnë kudo.”",id:"note-168-job-titles-change",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/168-job-titles-change.jpg?v=55556fab1e"},{q:"“Kujdesem veçanërisht që një problem i hapur të mos duket i mbyllur vetëm sepse turni im po mbaron.”",id:"note-169-care-especially-unclosed",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/169-care-especially-unclosed.jpg?v=887233082c"},{q:"“Gjatë zhvillimit kuptova se sfida më e rëndësishme nuk ishte të krijoja një faqe të bukur. Ishte ta organizoja informacionin në mënyrë që të mund të përdorej, të kontrollohej dhe të përmirësohej.”",id:"note-170-building-understood-most",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/170-building-understood-most.jpg?v=6182051da3"},{q:"“Nëse ekipi e kupton një KPI në një mënyrë dhe raporti e llogarit në një tjetër, besimi humbet që para se të shihet rezultati i parë.”",id:"note-171-if-team-understands",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/171-if-team-understands.jpg?v=dfc83bb102"},{q:"“Pyetja nuk është nëse sot është më keq se mesatarja. Shumë ditë do të jenë. Pyetja është nëse sot është më keq nga sa e lejon luhatja normale e këtij procesi.”",id:"note-172-question-whether-today",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/172-question-whether-today.jpg?v=efd6465bfe"},{q:"“Në operacione, tundimi është gjithmonë të hidhesh drejt e te zgjidhja. KPI-ja del keq dhe dikush e ka zgjidhjen gati.”",id:"note-173-operations-temptation-always",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/173-operations-temptation-always.jpg?v=407bbad7a5"},{q:"“Je aq brenda punës sa mund të mos e shohësh më procesin si proces.”",id:"note-174-far-inside-work",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/174-far-inside-work.jpg?v=bb46610443"},{q:"“Një premtim që nuk varet nga ti nuk e zgjidh problemin. E shtyn për në mëngjes dhe e bën më të rëndë.”",id:"note-175-promise-depend-solve",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/175-promise-depend-solve.jpg?v=b25e681fce"},{q:"“Shoferi e sheh problemin. Dispeçeri sheh efektin e tij mbi gjithë turnin. Menaxheri duhet të kuptojë pse ekziston problemi.”",id:"note-176-driver-sees-problem",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/176-driver-sees-problem.jpg?v=09d3ac20c0"},{q:"“Një SOP nuk mund të trajtohet si dokument që shkruhet një herë dhe pastaj harrohet.”",id:"note-177-sop-cannot-treated",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/177-sop-cannot-treated.jpg?v=fb52a48a7b"},{q:"“Nuk është gjithmonë mirë që një drejtues të bëhet personi që zgjidh gjithçka.”",id:"note-178-always-good-leader",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/178-always-good-leader.jpg?v=d3a4c6ef9d"},{q:"“Një takim para turnit humbet vlerën kur mbetet vetëm te numrat.”",id:"note-179-briefing-loses-value",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/179-briefing-loses-value.jpg?v=42a2cac2d6"},{q:"“Brenda një ekipi zakonisht dihet kush bën çfarë. Ka një përgjegjës, një standard, një ritëm. Por puna rrallë mbetet brenda një ekipi të vetëm.”",id:"note-180-inside-team-usually",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/180-inside-team-usually.jpg?v=b0caab5ff6"},{q:"“Nëse shohim vetëm personin, rrezikojmë të lëmë të paprekur një proces që do ta prodhojë sërish të njëjtin problem.”",id:"note-181-if-look-only",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/181-if-look-only.jpg?v=4e602016a9"},{q:"“Një menaxher duhet të dallojë mungesën e aftësisë profesionale nga një pengesë komunikimi. Janë dy probleme të ndryshme dhe kërkojnë zgjidhje të ndryshme.”",id:"note-182-manager-tell-lack",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/182-manager-tell-lack.jpg?v=96470198a8"},{q:"“Kur procesi nuk është i shkruar si një rrugë e qartë, ai jeton te personi që e bën çdo ditë.”",id:"note-183-when-process-written",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/183-when-process-written.jpg?v=c3d7d9a3d9"},{q:"“Kur një informacion arrin vonë, vonesa vetë është sinjal. Problemi ka pasur kohë të rritet para se ta mësosh.”",id:"note-184-when-information-arrives",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/184-when-information-arrives.jpg?v=de8b42bfe9"},{q:"“Në letër kishte rezervë. Në praktikë, rezerva ishte zënë tashmë.”",id:"note-185-paper-there-was",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/185-paper-there-was.jpg?v=b548d5dc34"},{q:"“Një dokument i mirë është i dobishëm. Por vetëm ai nuk garanton që procesi të ndiqet saktë.”",id:"note-186-good-document-useful",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/186-good-document-useful.jpg?v=e5c43353d6"},{q:"“Kur një problem zgjidhet me nxitim, vendi është gjëja e parë që harrohet.”",id:"note-187-when-problem-solved",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/187-when-problem-solved.jpg?v=d0d9478732"},{q:"“Një korrigjim që përsëritet nuk është korrigjim. Është një gabim i sistemit që askush nuk e ka raportuar.”",id:"note-188-correction-repeats-correction",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/188-correction-repeats-correction.jpg?v=227fcbb7a5"},{q:"“Një numër i kuq nuk është terreni. Është një raport për terrenin, dhe çdo raport vjetrohet.”",id:"note-189-red-number-report",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/189-red-number-report.jpg?v=218b87c628"},{q:"“Ngjyra e kuqe është sinjal për të kontrolluar. Nuk është diagnozë.”",id:"note-190-signal-not-diagnosis",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/190-signal-not-diagnosis.jpg?v=c082d030bb"},{q:"“Një numër i kuq të thotë ku të shikosh. Nuk të thotë çfarë ka aty tani. Largësia mes të dyjave është vjetërsia e numrit, dhe ta dish atë është detyra jote.”",id:"note-191-where-to-look",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/191-where-to-look.jpg?v=ef6efd450c"},{q:"“Statusi në sistem dhe historia e plotë e një problemi nuk janë e njëjta gjë.”",id:"note-192-status-not-history",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/192-status-not-history.jpg?v=0a14fa7fbc"},{q:"“Sistemi e planifikon rrugën me të dhënat që ka. Shoferi e përshkon me kushtet që ka. Asnjëri nuk e ka pamjen e plotë pa tjetrin.”",id:"note-193-system-plans-tour",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/193-system-plans-tour.jpg?v=1b8dc8d95d"},{q:"“Një shofer me përvojë nuk duhet të jetë korrigjimi i përhershëm i një sistemi që nuk mëson.”",id:"note-194-experienced-driver-should",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/194-experienced-driver-should.jpg?v=49ab9db5dc"},{q:"“Problemi nuk është vetëm kur sistemi nuk e njeh rrugën. Problemi është kur organizata nuk mëson nga njerëzit që e përshkojnë çdo ditë.”",id:"note-195-problem-system-know",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/195-problem-system-know.jpg?v=0de95a9863"},{q:"“Rruga që shoferi nuk e kupton është ndonjëherë një gabim i planit, ndonjëherë një gjë që askush nuk ia ka shpjeguar. Cila nga të dyja është, e kupton vetëm kur dikush dëgjon, verifikon dhe e shkruan.”",id:"note-196-tour-driver-understand",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/196-tour-driver-understand.jpg?v=e4ba6e7c3d"},{q:"“Një regjistrim i saktë nuk është gjithmonë provë se procesi fizik ka përfunduar saktë.”",id:"note-197-accurate-record-always",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/197-accurate-record-always.jpg?v=d4c808c02d"},{q:"“Skaneri është dëshmitar i një veprimi. Gjykimi kërkon të kuptosh të gjithë procesin.”",id:"note-198-scanner-witness-action",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/198-scanner-witness-action.jpg?v=21b926bbd5"},{q:"“Sistemi të tregon çfarë është regjistruar. Menaxheri duhet të kuptojë çfarë ka ndodhur. Mes të dyjave është procesi dhe aty bëhet puna.”",id:"note-199-system-tells-been",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/199-system-tells-been.jpg?v=1844be69e6"},{q:"“Dy raporte me dy numra të ndryshëm nuk do të thotë që njëri gabon. Do të thotë që duhet të dish çfarë numëron secili.”",id:"note-200-two-reports-two",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/200-two-reports-two.jpg?v=ad1545de20"},{q:"“Gjenerimi i një raporti nuk do të thotë automatikisht që çdo çështje operative është mbyllur.”",id:"note-201-generating-report-automatically",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/201-generating-report-automatically.jpg?v=3e1e983d17"},{q:"“AI mund të më ndihmojë ta shkruaj më qartë një raport. Nuk duhet të vendosë vetë se çfarë është e vërtetë.”",id:"note-202-ai-help-me",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/202-ai-help-me.jpg?v=96f0b2d1f6"},{q:"“Raporti duhet të ndihmojë njeriun të kuptojë realitetin, jo ta zëvendësojë kontrollin e realitetit.”",id:"note-203-report-should-help",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/203-report-should-help.jpg?v=df11a3a2e3"},{q:"“Makina mund ta shkruajë raportin. Përgjegjësinë për atë që thotë raporti duhet ta mbajë njeriu.”",id:"note-204-machine-write-report",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/204-machine-write-report.jpg?v=5128f0fc74"},{q:"“Kur shumë procese varen nga një sistem, ndërprerja e tij ndikon jo vetëm në mënyrën si punojnë njerëzit, por edhe në mënyrën si mësojnë.”",id:"note-205-many-processes-depend",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/205-many-processes-depend.jpg?v=75209f6e84"},{q:"“Rikthimi i sistemit nuk është përfundimi i incidentit.”",id:"note-206-system-coming-back",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/206-system-coming-back.jpg?v=1b514edb45"},{q:"“Një operacion i përgatitur nuk është ai që bën sikur sistemi nuk do të ndalet kurrë. Është ai që e di si ta ruajë përgjegjësinë dhe vazhdimësinë e punës kur sistemi ndalet.”",id:"note-207-prepared-operation-pretends",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/207-prepared-operation-pretends.jpg?v=348612f0a0"},{q:"“Kur sistemi ndalet, kupton sa shumë nga puna jote varet prej tij dhe sa mirë je përgatitur për të vazhduar.”",id:"note-208-system-stops-realise",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/208-system-stops-realise.jpg?v=d34f8dc7b8"},{q:"“Një sistem i ri nuk bëhet pjesë e punës sepse është instaluar. Bëhet kur njerëzit e kuptojnë, dinë ta përdorin dhe dinë çfarë të bëjnë kur ai nuk i ndihmon.”",id:"note-209-new-system-become",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/209-new-system-become.jpg?v=963edef11d"},{q:"“Vështirësia e një sistemi të ri nuk është vetëm të dish ku të klikosh. Është të gjesh informacionin e duhur në momentin kur të duhet.”",id:"note-210-difficulty-new-system",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/210-difficulty-new-system.jpg?v=04c2449137"},{q:"“Instalimi e ndryshon sistemin. Trajnimi, komunikimi dhe përvoja e përditshme e ndryshojnë mënyrën si punojnë njerëzit.”",id:"note-211-installation-changes-system",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/211-installation-changes-system.jpg?v=643b2ffc89"},{q:"“Kur një punonjës ndërton një mjet për ta bërë punën më të lehtë, ndoshta po tregon një boshllëk në mënyrën si organizata e shpërndan informacionin.”",id:"note-212-employee-builds-tool",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/212-employee-builds-tool.jpg?v=5de074f731"},{q:"“Një mjet i dobishëm bëhet mjet i ekipit vetëm kur është i saktë, i përditësuar, i autorizuar për përdorimin që i jepet dhe i sigurt për informacionin që trajton.”",id:"note-213-useful-tool-becomes",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/213-useful-tool-becomes.jpg?v=df3e66798a"},{q:"“Një mjet i vogël mund të zgjidhë një problem të madh. Por që të bëhet pjesë e punës, duhet të jetë më shumë se projekti i personit që e ndërtoi.”",id:"note-214-small-tool-solve",d:"13 tetor 2026",iso:"2026-10-13",img:"/media/notes/sq/214-small-tool-solve.jpg?v=2851fca151"},{q:"“Izolimi të blen kohë. Shkakun nuk ta blen. Një 8D që ndalet te izolimi e ka nxjerrë problemin vetëm nga sytë e klientit.”",id:"note-215-containment-buys-time",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/215-containment-buys-time.jpg?v=8bd4a7cdd6"},{q:"“Çdo defekt që e pa klienti ka dy shkaqe: pse u krijua dhe pse askush nuk e kapi para se të dilte. Një 8D që rregullon vetëm të parin e lë të hapur pikën e rrjedhjes.”",id:"note-216-every-defect-customer",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/216-every-defect-customer.jpg?v=14219c6c5a"},{q:"“Një vlerësim rreziku i shkruar për inspektorin mbron letrën. Një i shkruar bashkë me njerëzit që e bëjnë punën mbron njerëzit.”",id:"note-217-risk-assessment-written",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/217-risk-assessment-written.jpg?v=b98d556096"},{q:"“Tabela paralajmëruese është vija e fundit e mbrojtjes, jo e para. Hiqe rrezikun para se t'u kërkosh njerëzve të kenë kujdes rreth tij.”",id:"note-218-warning-sign-last",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/218-warning-sign-last.jpg?v=9a5885a70a"},{q:"“Një strategji që askush në terren nuk di ta shpjegojë nuk është strategji. Është një slajd.”",id:"note-219-strategy-nobody-floor",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/219-strategy-nobody-floor.jpg?v=24ab439019"},{q:"“Objektivat që udhëtojnë vetëm poshtë kthehen si justifikime. Objektivat që shkëmbehen lart e poshtë kthehen si angazhime. Për këtë shërben catchball.”",id:"note-220-goals-only-travel",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/220-goals-only-travel.jpg?v=92ba598da9"},{q:"“Pjesa më e madhe e një ndërrimi të prodhimit është punë që mund të ishte bërë para se të ndalej makineria.”",id:"note-221-most-changeover-work",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/221-most-changeover-work.jpg?v=ca9013e2e0"},{q:"“Çdo minutë që ia heq një ndërrimi të prodhimit është një minutë që linja ta kthen pa asnjë person më shumë.”",id:"note-222-every-minute-take",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/222-every-minute-take.jpg?v=3a920c187f"},{q:"“Leader standard work ekziston për një arsye të vetme: që standardi i ekipit t'i mbijetojë ditës më të ngarkuar të drejtuesit.”",id:"note-223-leader-standard-work",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/223-leader-standard-work.jpg?v=dd0399fe31"},{q:"“Mungesa e stafit rrallë është befasi. Zakonisht është një parashikim që askush nuk e ktheu në kapacitet.”",id:"note-224-understaffing-rarely-surprise",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/224-understaffing-rarely-surprise.jpg?v=7080c97966"},{q:"“Orët shtesë nuk janë plan kapaciteti. Janë fatura që paguan kur nuk ke një të tillë.”",id:"note-225-overtime-capacity-plan",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/225-overtime-capacity-plan.jpg?v=91c87f136a"},{q:"“Nëse e numëron gjithë stokun me të njëjtin kujdes, stokun që ka rëndësi e numëron me shumë pak.”",id:"note-226-count-all-stock",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/226-count-all-stock.jpg?v=fb0bd659d1"},{q:"“Stoku i sigurisë nuk është ndjesi. Është çmimi i kërkesës që nuk mund ta parashikosh.”",id:"note-227-safety-stock-feeling",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/227-safety-stock-feeling.jpg?v=3f62d99c66"},{q:"“Një mysafir që pret në hollë rrallë është problem i housekeeping-ut. Zakonisht është një status dhome që askush nuk e përditësoi.”",id:"note-228-guest-waiting-lobby",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/228-guest-waiting-lobby.jpg?v=bb0bb8ed0d"},{q:"“Nëse çdo pastrueseje i jep të njëjtin numër dhomash si dje, nuk ke planifikuar asgjë: një nisje dhe një qëndrim i vazhduar nuk janë e njëjta punë.”",id:"note-229-give-every-attendant",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/229-give-every-attendant.jpg?v=bdb1e960d4"},{q:"“Rikuperimi i shërbimit fillon para kompensimit. Një mysafir që ndihet i dëgjuar shpesh kërkon më pak se një mysafir që ndihet i trajtuar si dosje.”",id:"note-230-service-recovery-begins",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/230-service-recovery-begins.jpg?v=bab4bb8068"},{q:"“Ankesa e një mysafiri nuk mbyllet kur mysafiri largohet nga recepsioni. Mbyllet kur e merr përsëri në telefon dhe përgjigjja është po.”",id:"note-231-guests-complaint-closed",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/231-guests-complaint-closed.jpg?v=08e9ab3f33"},{q:"“Mirëmbajtja parandaluese duket gjithmonë e shtrenjtë, derisa të llogarisësh prishjen që ajo ndaloi.”",id:"note-232-preventive-maintenance-always",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/232-preventive-maintenance-always.jpg?v=ec506e58fd"},{q:"“Një punë mirëmbajtjeje e shtyrë nuk është kohë e kursyer. Është një prishje me një datë që nuk e zgjodhe ti.”",id:"note-233-postponed-maintenance-job",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/233-postponed-maintenance-job.jpg?v=c1db1bf6cd"},{q:"“Një listë e mirë e mëngjesit nuk të tregon gjithçka që ndodhi. Të tregon tri gjërat që nuk presin.”",id:"note-234-good-morning-list",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/234-good-morning-list.jpg?v=8732fe397f"},{q:"“Krahasimi i pikave të punës krah për krah nuk bëhet për të shpallur më të dobëtën. Bëhet për të zbuluar çfarë bën më e mira që të tjerat nuk e bëjnë.”",id:"note-235-comparing-sites-side",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/235-comparing-sites-side.jpg?v=42d97cffc5"},{q:"“Një tabelë në mur arrin te njerëz që ekrani nuk i arrin kurrë. Ekipi që nuk hyn kurrë në sistem e lexon prapë atë që është në letër.”",id:"note-236-board-wall-reaches",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/236-board-wall-reaches.jpg?v=715542ac6d"},{q:"“Një veprim pa përgjegjës dhe pa datë është një dëshirë e shkruar në një mbledhje.”",id:"note-237-action-without-owner",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/237-action-without-owner.jpg?v=a7a7f083d5"},{q:"“Auditet me shtresa funksionojnë për një arsye: kur drejtuesi i pikës kontrollon të njëjtin standard si drejtuesi i ekipit, standardi pushon së qeni vetëm problemi i drejtuesit të ekipit.”",id:"note-238-layered-audits-work",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/238-layered-audits-work.jpg?v=20122cd59b"},{q:"“Nëse vetëm një person di ta bëjë punën, nuk ke proces. Ke një pushim që nuk mund ta miratosh.”",id:"note-239-if-only-one",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/239-if-only-one.jpg?v=e648af2349"},{q:"“Një dhomë e dhënë pa inspektim inspektohet gjithsesi: nga mysafiri, në momentin më të keq.”",id:"note-240-room-released-without",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/240-room-released-without.jpg?v=16900b1ba3"},{q:"“Askush nuk e shkruan ecjen në përshkrimin e punës. E megjithatë, në shumë turne, ecja është vetë puna.”",id:"note-241-nobody-writes-walking",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/241-nobody-writes-walking.jpg?v=f44df9a2c5"},{q:"“Një biznes familjar që i paguan fëmijët e vet me premtime nuk po ndërton të ardhmen. Po e harxhon atë.”",id:"note-242-family-business-pays",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/242-family-business-pays.jpg?v=46a0a7882e"},{q:"“Gjaku mund të jetë lidhje. Kur përdoret për t'i mohuar dikujt rrogën, bëhet zinxhir.”",id:"note-243-blood-bond-used",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/243-blood-bond-used.jpg?v=463db23f3e"},{q:"“Mbiemri mund të trashëgohet. Kompetenca jo.”",id:"note-244-surname-inherited-competence",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/244-surname-inherited-competence.jpg?v=46166a4be7"},{q:"“Kur pronari shpërblen atë që i kapërceu shkallët menaxherit, nuk shpëton një njeri. Fik sistemin.”",id:"note-245-when-owner-rewards",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/245-when-owner-rewards.jpg?v=a19c5188b8"},{q:"“Të ikësh në orar nuk është mungesë besnikërie. Orët shtesë të paplanifikuara çdo ditë janë mungesë menaxhimi.”",id:"note-246-going-home-when",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/246-going-home-when.jpg?v=48b3c5f89d"},{q:"“Kur largohet një njeri i mirë, nuk ka dështuar tregu. Ka dështuar menaxhimi.”",id:"note-247-when-good-person",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/247-when-good-person.jpg?v=de845f0709"},{q:"“Rroga nuk është bukë që të falin. Është çmimi i punës që ke dhënë.”",id:"note-248-wage-bread-given",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/248-wage-bread-given.jpg?v=a881af457d"},{q:"“Të djersitësh çdo ditë mbi të njëjtin dështim nuk është përkushtim. Është një proces që askush nuk e rregulloi.”",id:"note-249-sweating-every-day",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/249-sweating-every-day.jpg?v=6ad8dff4ca"},{q:"“Një rritje page që fyen kushton më shumë se asnjë rritje: u tregon njerëzve saktësisht sa vlente për ty viti i tyre.”",id:"note-250-pay-rise-insults",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/250-pay-rise-insults.jpg?v=fd5e412ed0"},{q:"“Kur Burimet Njerëzore harrojnë njeriun, nuk mbetet gjë tjetër veç vulës.”",id:"note-251-when-human-resources",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/251-when-human-resources.jpg?v=d8628f587a"},{q:"“Zhurma e lëvizjes nuk është përparim. Një drejtues që ka nevojë të duket i zënë zakonisht ka pushuar së pari punën.”",id:"note-252-noise-motion-progress",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/252-noise-motion-progress.jpg?v=3a157e4a88"},{q:"“Një makineri që punon gjithë turnin nuk është domosdoshmërisht makineri që prodhon. OEE ta tregon diferencën në minuta.”",id:"note-253-machine-runs-all",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/253-machine-runs-all.jpg?v=ec2a23b4bb"},{q:"“Humbja më e madhe rrallë është prishja që e mbajnë mend të gjithë. Janë ndalesat e vogla që askush nuk i shkruan.”",id:"note-254-biggest-loss-rarely",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/254-biggest-loss-rarely.jpg?v=6dc62f5bba"},{q:"“Një fishbone i plotësuar nga një person i vetëm është një hamendje me një diagram përreth.”",id:"note-255-fishbone-filled-by",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/255-fishbone-filled-by.jpg?v=cfaf37e173"},{q:"“Një FMEA e bën pyetjen e pakëndshme sa përgjigjja është ende e lirë: si mund të dështojë ky hap?”",id:"note-256-fmea-asks-uncomfortable",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/256-fmea-asks-uncomfortable.jpg?v=816a9ab2e7"},{q:"“Një linjë nuk balancohet me mendime se sa zgjat një punë. Kronometri është më i drejtë se ndjesia.”",id:"note-257-cannot-balance-line",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/257-cannot-balance-line.jpg?v=7e28001fc5"},{q:"“Takti nuk është objektiv drejt të cilit shtyn njerëzit. Është ritmi që vendos kërkesa.”",id:"note-258-takt-target-push",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/258-takt-target-push.jpg?v=f12b4a8b99"},{q:"“Në shumicën e rrjedhave të vlerës puna vetë është e shpejtë. Është pritja mes hapave që e vonon porosinë.”",id:"note-259-most-value-streams",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/259-most-value-streams.jpg?v=df2d6987b2"},{q:"“Një pikë kyçe pa arsye është një rregull që njerëzit e braktisin ditën e parë të ngarkuar.”",id:"note-260-key-point-without",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/260-key-point-without.jpg?v=c166feef6b"},{q:"“Nëse problemi nuk nxë në një fletë A3, ende nuk e ke kuptuar. Vetëm e ke mbledhur.”",id:"note-261-if-problem-fit",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/261-if-problem-fit.jpg?v=d9f4453ce2"},{q:"“Një ide përmirësimi që pret tre muaj për një përgjigje e mëson ekipin të mos ketë më ide.”",id:"note-262-improvement-idea-waits",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/262-improvement-idea-waits.jpg?v=cdda7dfcf3"},{q:"“Një kaizen event nuk provohet ditën e fundit të punëtorisë. Provohet te kontrolli i 30 ditëve, kur askush nuk po shikon më.”",id:"note-263-kaizen-event-proven",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/263-kaizen-event-proven.jpg?v=c42ee0800f"},{q:"“Një incident i shmangur për pak është mësim falas. I radhës mund të vijë me faturë.”",id:"note-264-near-miss-free",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/264-near-miss-free.jpg?v=ff019cad29"},{q:"“Etiketa e kuqe nuk është ndëshkim për sendin. Është një pyetje: a e meriton ende vendin këtu?”",id:"note-265-red-tag-punishment",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/265-red-tag-punishment.jpg?v=ecffa9f90f"},{q:"“Mbushja mund të jetë e lartë dhe nata prapë të humbasë para. RevPAR të tregon nëse dhomat fituan aq sa mund të fitonin.”",id:"note-266-occupancy-high-night",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/266-occupancy-high-night.jpg?v=5747124e8f"},{q:"“Night audit është vendi ku premtimet e ditës takojnë regjistrimet e ditës. Çdo boshllëk i gjetur natën kushton më pak se një i gjetur nga mysafiri.”",id:"note-267-night-audit-where",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/267-night-audit-where.jpg?v=5b03ea7403"},{q:"“Sendet e humbura janë një regjistër i vogël me një premtim të madh: atë që harroi mysafiri, nuk e harruam ne.”",id:"note-268-lost-property-small",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/268-lost-property-small.jpg?v=8db9725975"},{q:"“Një takim i shkurtër që lexon vetëm shifrat e djeshme është raport. Një takim që vendos një veprim për sot është menaxhim.”",id:"note-269-huddle-only-reads",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/269-huddle-only-reads.jpg?v=0c4acea045"},{q:"“Një raport javor duhet të mbyllet me një vendim, jo me një përmbledhje. Përndryshe është shkruar për t'u arkivuar, jo për t'u lexuar.”",id:"note-270-weekly-report-should",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/270-weekly-report-should.jpg?v=aae191fef6"},{q:"“Dhjetë projekte në punë shpesh janë zero projekte të mbaruara. Një portofol të tregon cilin ta ndalosh.”",id:"note-271-ten-projects-progress",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/271-ten-projects-progress.jpg?v=e368b72f6a"},{q:"“Një proces mund të jetë nën kontroll dhe prapë të mos jetë i aftë. I qëndrueshëm dhe mjaftueshëm i mirë janë dy pyetje të ndryshme.”",id:"note-272-process-control-still",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/272-process-control-still.jpg?v=2ab8234f66"},{q:"“CV-ja nuk është lista e punëve që ke bërë. Është prova e problemeve që ke zgjidhur.”",id:"note-273-cv-list-jobs",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/273-cv-list-jobs.jpg?v=716ce14b40"},{q:"“Një letër motivimi që mund t'i dërgohet çdo kompanie nuk do ta lexojë asnjë.”",id:"note-274-cover-letter-could",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/274-cover-letter-could.jpg?v=7224b9aad2"},{q:"“Kur një proces funksionon vetëm sepse njerëzit e ndreqin vazhdimisht, nuk po funksionon procesi. Po funksionojnë njerëzit.”",id:"note-275-when-process-works",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/275-when-process-works.jpg?v=2b03d258be"},{q:"“Ndreqja e shpejtë nuk është të mësuar i shpejtë. I njëjti korrigjim dy herë është i njëjti gabim dy herë.”",id:"note-276-fixing-fast-learning",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/276-fixing-fast-learning.jpg?v=c629ee63af"},{q:"“Një zgjidhje e përkohshme është një mesazh nga terreni. Ndëshkoje dhe mesazhi ndalet. Problemi jo.”",id:"note-277-workaround-message-from",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/277-workaround-message-from.jpg?v=118dd86af9"},{q:"“Kolegu që gjithmonë e di nuk është zgjidhje. Është një varësi që askush nuk e shkroi.”",id:"note-278-colleague-who-always",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/278-colleague-who-always.jpg?v=72ece2b1c5"},{q:"“I njëjti njeri që këtu quhet dembel bëhet punonjës model jashtë. Nuk ndryshoi njeriu. Ndryshoi sistemi.”",id:"note-279-same-person-called",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/279-same-person-called.jpg?v=27111448fb"},{q:"“Fajësimi i dembelizmit të një populli është alibia më e lehtë që mund të gjejë një menaxhim i dështuar.”",id:"note-280-blaming-laziness-people",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/280-blaming-laziness-people.jpg?v=41ca50b0c8"},{q:"“Nëse emergjenca jote është detyra ime në mesnatë, rroga ime nuk është çështje për orarin e zyrës.”",id:"note-281-if-your-emergency",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/281-if-your-emergency.jpg?v=8a5a87015a"},{q:"“Rroga blen punën tënde, jo kohën tënde të lirë. Një telefon që duhet të jetë gjithmonë hapur është punë e papaguar.”",id:"note-282-wage-buys-your",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/282-wage-buys-your.jpg?v=b01932100a"},{q:"“Dy ditë trajnim nuk janë përshtatje në punë. Janë një ultimatum me buzëqeshje.”",id:"note-283-two-days-training",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/283-two-days-training.jpg?v=c9c19d5474"},{q:"“Kur një dyqan ecën me kujtesën e pronarit, çdo njeri i ri është i dënuar të gabojë.”",id:"note-284-when-shop-runs",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/284-when-shop-runs.jpg?v=bdd70847f0"},{q:"“Pagimi i rrogës nuk është bamirësi. Është kontrata që pronari firmosi kur punësoi dikë.”",id:"note-285-paying-wages-charity",d:"25 tetor 2026",iso:"2026-10-25",img:"/media/notes/sq/285-paying-wages-charity.jpg?v=ae44282025"},{q:"“Aty ku gjithçka është urgjente, asgjë nuk është e rëndësishme. Nxitimi i vazhdueshëm është maskimi më komod i mungesës së planifikimit.”",id:"note-286-everything-urgent-nothing",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/286-everything-urgent-nothing.jpg?v=b5bb2e36fe"},{q:"“Gjuetia e fajtorit nuk është drejtësi. Kur dënimi zëvendëson analizën e shkakut rrënjësor, i njëjti dështim është rezervuar tashmë për nesër.”",id:"note-287-hunting-culprit-not",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/287-hunting-culprit-not.jpg?v=d7542af2a1"},{q:"“Përballë një padrejtësie të hapur, neutraliteti nuk ekziston. Heshtja nuk është paqe. Është një votë e qetë për atë që po shkel mbi të tjerët.”",id:"note-288-silence-not-peace",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/288-silence-not-peace.jpg?v=6dcb6a7cd6"},{q:"“Një kosto nuk zhduket ngaqë kompania pushoi së paguari për të. Ndryshon departament dhe bie mbi dikë që nuk ishte në sallë.”",id:"note-289-cost-does-not",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/289-cost-does-not.jpg?v=7eaa684e71"},{q:"“Një drejtues nuk i detyrohet besnikëri çdo vendimi të marrë. Vetëm vendimit më të mirë që mundet, me të vërtetën që ka përpara sot.”",id:"note-290-loyal-best-decision",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/290-loyal-best-decision.jpg?v=51c71f247f"},{q:"“Vlera jote nuk matet me sa i pazëvendësueshëm bëhesh duke fshehur dijen. Matet me sa të pavarur i bën njerëzit përreth teje.”",id:"note-291-hiding-knowledge-value",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/291-hiding-knowledge-value.jpg?v=08fdc26030"},{q:"“Pushteti mund t'i detyrojë njerëzit të të japin përgjigje. Nuk mund t'i detyrojë të të thonë të vërtetën, nëse ua ke mësuar frikën prej saj.”",id:"note-292-power-forces-answers",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/292-power-forces-answers.jpg?v=b22472ea4a"},{q:"“Një raport i gjelbër vërteton se objektivi u arrit. Nuk vërteton se mënyra si u arrit ishte e drejtë. Pyet çfarë duhej të mos shihej.”",id:"note-293-green-report-proves",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/293-green-report-proves.jpg?v=829b603aa5"},{q:"“Një problem nuk bëhet përgjegjësi e të gjithëve vetëm ngaqë e diskutuan të gjithë. Një mbledhje pa përgjegjës e lë vendimin jetim.”",id:"note-294-problem-discussed-many",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/294-problem-discussed-many.jpg?v=2ed1ff56c4"},{q:"“Makina mund të kursejë një orë. Vetëm njeriu vendos nëse ajo orë bëhet më shumë vlerë, më shumë liri apo thjesht më shumë punë.”",id:"note-295-machine-saves-hour",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/295-machine-saves-hour.jpg?v=9eada7d0c9"},{q:"“Kur ata që vendosin janë të mbrojtur nga pasojat, gabimi nuk është më një mundësi. Është një garanci.”",id:"note-296-shielded-from-consequences",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/296-shielded-from-consequences.jpg?v=0469ee6c35"},{q:"“Drejtuesi që nuk di të ndërtojë bashkëpunim me proces, ndërton klane me intrigë. Një ekip i ndarë nuk ka kurrë kohë të shohë boshllëkun në krye.”",id:"note-297-divided-team-never",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/297-divided-team-never.jpg?v=e5da2b2606"},{q:"“Pesë fjalë e provojnë karakterin e një drejtuesi: Unë dhashë urdhrin e gabuar. Thënë përpara njerëzve, jo i fshehur pas tyre.”",id:"note-298-wrong-order-stand",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/298-wrong-order-stand.jpg?v=abd22fd568"},{q:"“Testi moral i një profesionisti nuk jepet para duartrokitjeve. Jepet vetëm në dyshemenë e punës, aty ku kompromisi i lehtë të tundon çdo sekondë.”",id:"note-299-moral-test-floor",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/299-moral-test-floor.jpg?v=1bef1a986f"},{q:"“Padrejtësia nuk fillon vetëm kur dikujt i jepet më pak. Ndonjëherë fillon kur prej tij kërkohet shumë më tepër, ndërsa të gjithë këmbëngulin se askush nuk u trajtua ndryshe.”",id:"note-300-injustice-asking-more",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/300-injustice-asking-more.jpg?v=b741d1db37"},{q:"“Rregullat që ndalen te dera e menaxherit nuk e mbrojnë më organizatën nga arbitrariteti. Mbrojnë arbitraritetin e menaxherit nga organizata.”",id:"note-301-rules-manager-door",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/301-rules-manager-door.jpg?v=6b6b7d3ae9"},{q:"“Kush nuk di të thotë kurrë jo, nuk është besnik. Thjesht nuk ka kufij, dhe aty ku mbarojnë kufijtë e njeriut, fillon shfrytëzimi.”",id:"note-302-never-saying-no",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/302-never-saying-no.jpg?v=3369d43114"},{q:"“Suksesi më i trishtë është ai që e ndërton me aq përkushtim, sa kur më në fund ngre kokën, një pjesë e jetës që duhej të mbushte ka kaluar pa ty.”",id:"note-303-saddest-success-built",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/303-saddest-success-built.jpg?v=074dfc1848"},{q:"“Lavdia më e vështirë në operacione është një rezultat që nuk e vë re askush, sepse nuk u desh që diçka të shkonte keq për ta bërë punën tënde të dukshme.”",id:"note-304-glory-nothing-went",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/304-glory-nothing-went.jpg?v=135612d80a"},{q:"“Një organizatë mund ta ngatërrojë për vite qëndrueshmërinë e saj me aftësinë e një njeriu për të mbuluar dobësitë e të gjithë të tjerëve. Kjo nuk është forcë. Është një dështim i pranuar në heshtje.”",id:"note-305-stability-one-person",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/305-stability-one-person.jpg?v=518ebe9d15"},{q:"“Drejtuesi që nuk e di të vërtetën shpesh e ka bërë vetë këtë, vendim pas vendimi, duke e shpallur të vërtetën armike të zyrës së tij.”",id:"note-306-truth-enemy-office",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/306-truth-enemy-office.jpg?v=2e2935ce85"},{q:"“Kur Burimet Njerëzore pushojnë së mbrojturi standardin dhe fillojnë t'i vënë vulën arbitraritetit, nuk janë më funksion menaxhimi. Janë bashkëfajtore.”",id:"note-307-hr-notary-arbitrary",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/307-hr-notary-arbitrary.jpg?v=fd12ecac21"},{q:"“Pronari që lufton të mposhtë stafin e vet në dije, autoritet dhe ego nuk po mbron kompaninë. Po shkatërron investimin e vet.”",id:"note-308-owner-outdo-staff",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/308-owner-outdo-staff.jpg?v=1f9f510cda"},{q:"“Nuk mund të hedhësh çdo ditë helm në pusin e fshatit dhe pastaj të çuditesh me fqinjët pse uji po i sëmur fëmijët.”",id:"note-309-poison-village-well",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/309-poison-village-well.jpg?v=92a2aa1afe"},{q:"“Rregullat tregojnë ku mbaron përgjegjësia jonë. Brenda tyre, gjykimi tregon sa seriozisht e marrim njeriun. Rregullorja nuk duhet të mbyllë ndërgjegjen e atij që e zbaton.”",id:"note-310-rules-judgement-person",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/310-rules-judgement-person.jpg?v=857a24c9e1"},{q:"“Një ekip mund të shkatërrohet jo nga një punonjës i dobët, por kur të gjithë mësojnë se për ta mbajtur një talent duhet të pranojnë të vlejnë më pak.”",id:"note-311-talent-worth-less",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/311-talent-worth-less.jpg?v=8aa8a10873"},{q:"“Pushteti nuk e korrupton njeriun. I heq perden asaj që ishte aty para se të ulej në karrige.”",id:"note-312-power-pulls-curtain",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/312-power-pulls-curtain.jpg?v=ed11e773bd"},{q:"“Ka një rehati të rrezikshme te roli i viktimës: nëse gjithçka është faj i të tjerëve, ti je i shfajësuar nga veprimi.”",id:"note-313-comfort-of-victim",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/313-comfort-of-victim.jpg?v=baae407175"},{q:"“Të ngatërrosh kaosin me pasionin dhe rregullin me ngathtësinë është shenja më e qartë e një kompanie që nuk di të gjykojë veten.”",id:"note-314-chaos-for-passion",d:"1 nëntor 2026",iso:"2026-11-01",img:"/media/notes/sq/314-chaos-for-passion.jpg?v=c9a3d26bd1"}];